tool_input.code:
const cmd = `$d='D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts\\_ov2_cc'
$out=@()
Get-ChildItem $d -Filter *.json | ForEach-Object {
  $j = Get-Content $_.FullName -Raw | ConvertFrom-Json
  foreach($r in $j.rows){
    $t = $r.text
    if($t -match '\\$\\s?\\d|\\d+\\s?(?:/hr|per hour|an hour|/hour|usd|USD|£|€)'){
      $out += [PSCustomObject]@{ q=$j.query; date=$r.created; title=$r.title; topic=$r.topicId; txt=$t }
    }
  }
}
Write-Output ("HITS=" + $out.Count)
$out | ForEach-Object {
  Write-Output ("### [" + $_.date + "] " + $_.title + "  (topic " + $_.topic + ")")
  Write-Output ("   " + $_.txt)
  Write-Output ""
}`;
const r = await tools.pwsh({ description: "Extract price-bearing CC posts", command: cmd });
const txt = r.kind === 'foreground' ? r.stdout.text : JSON.stringify(r);
console.log(txt.slice(0, 12000));
